#Requires -Version 5.1
<#
  gen-checksums.ps1 -- 生成 checksums.txt

  install.ps1 会读取同目录的 checksums.txt，比对字节数与 SHA256。
  每次修改任一脚本后，重新跑一次本脚本：

      .\gen-checksums.ps1

  输出格式（每行）：
      <文件名>|<字节数>|<SHA256 大写>
#>
param(
    [string]$Path = $PSScriptRoot
)

$ErrorActionPreference = 'Stop'

if (-not $Path) { $Path = (Get-Location).Path }

$files = @(
    'clipsync.ps1',
    'clipsync-guard.ps1',
    'clipsync-ctl.ps1',
    'install.ps1'
)

$lines = @(
    '# clipsync checksums',
    '# generated by gen-checksums.ps1 -- do not edit by hand',
    '# format: <file>|<bytes>|<sha256>'
)

Write-Host "生成校验和：$Path" -ForegroundColor Cyan
$missing = 0
foreach ($n in $files) {
    $p = Join-Path $Path $n
    if (-not (Test-Path -LiteralPath $p)) {
        Write-Host ("  缺失: {0}" -f $n) -ForegroundColor Yellow
        $missing++
        continue
    }
    $len = (Get-Item -LiteralPath $p).Length
    $h   = (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash
    $lines += ("{0}|{1}|{2}" -f $n, $len, $h)
    Write-Host ("  {0,-22} {1,7} B  {2}" -f $n, $len, $h.Substring(0, 16) + '...') -ForegroundColor Green
}

$out = Join-Path $Path 'checksums.txt'
[System.IO.File]::WriteAllLines($out, $lines, (New-Object System.Text.UTF8Encoding $true))

Write-Host ""
Write-Host ("已写入: {0}" -f $out) -ForegroundColor Green
if ($missing -gt 0) {
    Write-Host ("注意：有 {0} 个文件缺失，未写入校验和。" -f $missing) -ForegroundColor Yellow
    exit 1
}
